import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"EmakiStation","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/station/index.md","filePath":"en/modules/station/index.md","lastUpdated":0}`),a={name:`en/modules/station/index.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="emakistation" tabindex="-1">EmakiStation <a class="header-anchor" href="#emakistation" aria-label="Permalink to “EmakiStation”">​</a></h1><p>EmakiStation is the general-purpose crafting station of the Emaki series. You submit materials against a recipe, the craft joins a queue, and you collect the output when it is ready. The whole flow is a GUI station you can configure, and the module also ships a fully independent dismantling station</p><p>The crafting side is a three-page window (recipe catalog → material preview → craft queue) with a serial queue: only the head entry advances. Materials come from one merged pool of your inventory and the warehouse, and the warehouse joins in once EmakiStorage is installed. Outputs go to the warehouse or your inventory; when neither can accept them, the entry becomes pending-claim and waits for you, and nothing is ever dropped or destroyed</p><h2 id="basic-information" tabindex="-1">Basic Information <a class="header-anchor" href="#basic-information" aria-label="Permalink to “Basic Information”">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Value</th></tr></thead><tbody><tr><td>Module version</td><td><code>2.0.0</code></td></tr><tr><td>API coordinates</td><td><code>emaki.jiuwu.craft:emaki-station-api:2.0.0</code></td></tr><tr><td>Main class</td><td><code>emaki.jiuwu.craft.station.EmakiStationPlugin</code></td></tr><tr><td>Main command</td><td><code>/emakistation</code></td></tr><tr><td>Aliases</td><td><code>/estation</code>, <code>/est</code></td></tr><tr><td>Required dependency</td><td>EmakiCoreLib</td></tr><tr><td>Optional dependencies</td><td>EmakiStorage, PlaceholderAPI</td></tr><tr><td>Descriptor baseline</td><td><code>api-version: &quot;26.1&quot;</code>, <code>folia-supported: true</code></td></tr><tr><td>Java</td><td>Java 25</td></tr><tr><td>Main permissions</td><td><code>emakistation.use</code> (default true), <code>emakistation.purchase</code> (default true), <code>emakistation.dismantle</code> (default true), <code>emakistation.reload</code> (op), <code>emakistation.debug</code> (op), <code>emakistation.admin</code> (op)</td></tr></tbody></table><p>Three version numbers appear here, so sort them out first: the module, its default <code>config.yml</code>, and the API artifact all carry <code>2.0.0</code>. The source constant <code>AppConfig.CURRENT_VERSION = &quot;1.0.2&quot;</code> is a configuration-migration marker with a different job, so do not mix the three up</p><h2 id="feature-pages" tabindex="-1">Feature Pages <a class="header-anchor" href="#feature-pages" aria-label="Permalink to “Feature Pages”">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Contents</th></tr></thead><tbody><tr><td><a href="./commands.html">Commands and Permissions</a></td><td>The 9 functional subcommands (plus <code>help</code>), 6 permission nodes and two access-permission prefixes of <code>/emakistation</code></td></tr><tr><td><a href="./configuration.html">Configuration</a></td><td>The <code>queue</code>, <code>limits</code>, <code>storage</code>, <code>persistence</code> and <code>gui</code> sections of <code>config.yml</code>, with full key tables and defaults</td></tr><tr><td><a href="./stations.html">Station Definitions</a></td><td>Layouts, permissions, queue parameters, material channels, output routing and the condition gate in <code>stations/&lt;id&gt;.yml</code></td></tr><tr><td><a href="./recipes.html">Recipe Definitions</a></td><td>Ownership, materials, outputs, duration, currency cost, action sections and the two condition gates in <code>recipes/&lt;recipe&gt;.yml</code></td></tr><tr><td><a href="./queue.html">Craft Queue</a></td><td>The three sources of queue length, serial progression, cancellation refunds and the pending-claim state</td></tr><tr><td><a href="./queue-costs.html">Paid Queue Slots</a></td><td>The tiers, per-slot pricing, three switches and the <code>unlocks.yml</code> purchased-slot save of <code>queue_costs.yml</code></td></tr><tr><td><a href="./dismantle.html">Dismantling</a></td><td>Independent dismantle stations plus <code>item_sources</code>, <code>rolls</code> and weighted <code>pool</code> rolling</td></tr><tr><td><a href="./gui.html">GUI Templates</a></td><td>Slot types of the four GUI templates, the complete placeholder reference and the &quot;<code>type:</code> must be explicit&quot; rule</td></tr><tr><td><a href="./api.html">API and Integration</a></td><td>The facade, query and operation layers of <code>emaki-station-api</code> and their thread constraints</td></tr><tr><td><a href="./events.html">Event API</a></td><td><code>StationCraftSubmitEvent</code>, <code>StationCraftCancelEvent</code> and <code>StationCraftCompletedEvent</code></td></tr></tbody></table><h2 id="core-capabilities" tabindex="-1">Core Capabilities <a class="header-anchor" href="#core-capabilities" aria-label="Permalink to “Core Capabilities”">​</a></h2><ul><li><strong>Unordered set matching:</strong> a recipe only counts material kinds and totals, never where items sit, and there is no shaped concept. <code>item_sources</code> is an &quot;any of these&quot; set whose amount adds up across the whole set -- needing 64 is satisfied by 30 coal plus 34 charcoal</li><li><strong>Merged inventory and warehouse supply:</strong> with both channels enabled, materials come from one merged pool that spends your inventory first. You see no channel toggle; the &quot;owned&quot; figure in the window is already the combined total</li><li><strong>Serial single-line queue:</strong> you have one queue per station, and only the head entry advances. <code>waiting</code> and <code>running</code> occupy queue length while <code>pending_claim</code> does not</li><li><strong>Three sources of queue length:</strong> your queue length comes from the base length, the <code>emakistation.queue.&lt;n&gt;</code> permission tier, and paid purchases. The tier <strong>replaces</strong> the base length, purchased slots <strong>stack</strong> on top, and <code>max_length</code> clamps the result</li><li><strong>Outputs are never lost:</strong> when every configured target is full, the entry turns into pending-claim and waits for you to run <code>/emakistation claim</code> or click the in-window button</li><li><strong>Dismantling is fully independent:</strong> dismantle station ids are unrelated to crafting station ids and load from their own <code>stations_dismantle/</code> and <code>recipes_dismantle/</code> directories. It is not a fourth page of a crafting station</li></ul><h2 id="file-layout" tabindex="-1">File Layout <a class="header-anchor" href="#file-layout" aria-label="Permalink to “File Layout”">​</a></h2><p>Once the server has run, these are the files you will work with:</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>plugins/EmakiStation/</span></span>
<span class="line"><span>├─ config.yml</span></span>
<span class="line"><span>├─ queue_costs.yml</span></span>
<span class="line"><span>├─ stations/</span></span>
<span class="line"><span>│  ├─ blacksmith.yml</span></span>
<span class="line"><span>│  └─ example_altar.yml</span></span>
<span class="line"><span>├─ recipes/</span></span>
<span class="line"><span>│  ├─ example_recipe.yml</span></span>
<span class="line"><span>│  ├─ example_component_recipe.yml</span></span>
<span class="line"><span>│  ├─ example_weapon_recipe.yml</span></span>
<span class="line"><span>│  └─ example_queue_recipe.yml</span></span>
<span class="line"><span>├─ stations_dismantle/</span></span>
<span class="line"><span>│  ├─ example_dismantle_station.yml</span></span>
<span class="line"><span>│  └─ example_weapon_dismantle_station.yml</span></span>
<span class="line"><span>├─ recipes_dismantle/</span></span>
<span class="line"><span>│  ├─ example_dismantle_recipe.yml</span></span>
<span class="line"><span>│  ├─ example_component_dismantle_recipe.yml</span></span>
<span class="line"><span>│  └─ example_weapon_dismantle_recipe.yml</span></span>
<span class="line"><span>├─ gui/</span></span>
<span class="line"><span>│  ├─ station_catalog.yml</span></span>
<span class="line"><span>│  ├─ station_preview.yml</span></span>
<span class="line"><span>│  ├─ station_queue.yml</span></span>
<span class="line"><span>│  ├─ station_dismantle.yml</span></span>
<span class="line"><span>│  ├─ editor_browser_gui.yml</span></span>
<span class="line"><span>│  └─ editor_page_gui.yml</span></span>
<span class="line"><span>├─ data/</span></span>
<span class="line"><span>│  └─ &lt;UUID&gt;/</span></span>
<span class="line"><span>│     └─ unlocks.yml</span></span>
<span class="line"><span>└─ lang/</span></span>
<span class="line"><span>   ├─ zh_CN.yml</span></span>
<span class="line"><span>   └─ en_US.yml</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Path</th><th>Description</th></tr></thead><tbody><tr><td><code>config.yml</code></td><td>Main configuration: queue defaults, capacity limits, warehouse channel, persistence, GUI throttling</td></tr><tr><td><code>queue_costs.yml</code></td><td>Paid queue slot tiers. A business data file: released once when missing, never overwritten by version upgrades</td></tr><tr><td><code>stations/&lt;id&gt;.yml</code></td><td>Crafting station definition. The file name matches <code>id</code></td></tr><tr><td><code>recipes/&lt;recipe&gt;.yml</code></td><td>Crafting recipe definition. One recipe per file; ownership is declared recipe-side via <code>station_ids</code></td></tr><tr><td><code>stations_dismantle/&lt;id&gt;.yml</code></td><td>Dismantle station definition, unrelated to crafting stations</td></tr><tr><td><code>recipes_dismantle/&lt;recipe&gt;.yml</code></td><td>Dismantle recipe definition with an input item and a weighted output pool</td></tr><tr><td><code>gui/*.yml</code></td><td>Four window templates: recipe catalog, material preview, craft queue, dismantle window</td></tr><tr><td><code>data/&lt;player UUID&gt;/unlocks.yml</code></td><td>Per-player purchased-slot save, maintained by the plugin; not created when there are no purchased slots. See <a href="./queue-costs.html">Paid Queue Slots</a></td></tr><tr><td><code>lang/*.yml</code></td><td>Command, window, precheck and console messages</td></tr></tbody></table><h2 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to “Getting Started”">​</a></h2><ol><li>Drop <code>EmakiCoreLib-*.jar</code> and <code>EmakiStation-*.jar</code> into the server <code>plugins/</code> folder</li><li>Do <strong>not</strong> put <code>emaki-station-api-*.jar</code> into <code>plugins/</code> -- the API Jar is a compile-time dependency for developers only</li><li>After the first start, open <code>plugins/EmakiStation/config.yml</code> and the example station <code>stations/blacksmith.yml</code> and give them a look</li><li>Open the example station:</li></ol><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/emakistation open blacksmith</span></span></code></pre></div><ol start="5"><li>Check your queue and claim your outputs:</li></ol><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/emakistation queue</span></span>
<span class="line"><span>/emakistation claim</span></span></code></pre></div><ol start="6"><li>After you edit the configuration, reload to apply it:</li></ol><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/emakistation reload</span></span></code></pre></div><h2 id="usage-notes" tabindex="-1">Usage Notes <a class="header-anchor" href="#usage-notes" aria-label="Permalink to “Usage Notes”">​</a></h2><ul><li>Watch out: a station&#39;s <code>channels.backpack</code> and <code>channels.storage</code> cannot both be false, or the station is refused at load time. A station that opens but can never be used is worse than a startup error, so the plugin fails fast</li><li><code>channels.default</code> is a retained key that <strong>no longer has any effect</strong>. After the channels were merged, &quot;which channel you are on&quot; no longer exists; the source still reads the key, but nothing consumes it, and it only remains so old configuration files do not report an unknown key</li><li>The warehouse channel needs more than <code>storage.enabled: true</code>: EmakiStorage must also provide the <code>emakistorage:atomic_batch</code> capability (a batch operation that either does everything or nothing). Without it the plugin will <strong>not</strong> fall back to withdrawing item by item, because that would make materials flash through your inventory</li><li><code>progress_mode: offline</code> only means &quot;the timer keeps running&quot;, not &quot;delivery while offline&quot;. Entries that come due while you are offline are merely due; settlement happens at your next login</li><li>Keep all three layout files (<code>layout</code>, <code>preview_layout</code>, <code>queue_layout</code>) in place. If one is missing, the startup precheck reports <code>missing_layout</code></li><li><strong>Deterministic maximum-flow material allocation:</strong> when you hit submit, the plugin puts every inventory stack and every warehouse item source into one graph and searches for a complete assignment across all requirements, instead of relying on declaration order. Narrower matcher requirements join the graph first, but the outcome is still judged globally; a failure means the current candidates genuinely cannot satisfy all requirements at once</li><li><strong>Not yet wired up:</strong> EmakiStation registers no action-stage ids and no PlaceholderAPI expansion. The recipe <code>actions.pre</code> / <code>success</code> / <code>failure</code>, <code>result.actions</code>, and the station-level and dismantle-station-level <code>condition</code> blocks are all parsed and stored but have no execution entry point today; <code>limits.batch_multiplier_max</code> is likewise parsed without taking part in any check. See <a href="./recipes.html">Recipe Definitions</a>, <a href="./stations.html">Station Definitions</a>, <a href="./dismantle.html">Dismantling</a> and <a href="./configuration.html">Configuration</a></li></ul>`,23)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};